-- KURO Lab portal tables. Existing SNS tables are untouched.
create table if not exists public.portal_preferences(user_id uuid primary key references auth.users(id) on delete cascade,preferences jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.portal_favorites(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,item_key text not null,item_type text not null,title text not null,href text not null,created_at timestamptz not null default now(),unique(user_id,item_key));
create table if not exists public.portal_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,item_key text not null,title text not null,href text not null,visited_at timestamptz not null default now(),unique(user_id,item_key));
create table if not exists public.portal_announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,href text,published boolean not null default false,created_at timestamptz not null default now(),starts_at timestamptz not null default now(),ends_at timestamptz);
create table if not exists public.portal_requests(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,guest_id uuid,message text not null check(char_length(message) between 5 and 500),status text not null default 'pending' check(status in('pending','reviewing','done')),created_at timestamptz not null default now());
create index if not exists portal_favorites_user_created_idx on public.portal_favorites(user_id,created_at desc);
create index if not exists portal_history_user_visited_idx on public.portal_history(user_id,visited_at desc);
create index if not exists portal_announcements_active_idx on public.portal_announcements(published,starts_at desc);
create index if not exists portal_requests_created_idx on public.portal_requests(created_at desc);
alter table public.portal_preferences enable row level security;alter table public.portal_favorites enable row level security;alter table public.portal_history enable row level security;alter table public.portal_announcements enable row level security;alter table public.portal_requests enable row level security;
create policy "portal_preferences_select_own" on public.portal_preferences for select to authenticated using(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_preferences_insert_own" on public.portal_preferences for insert to authenticated with check(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_preferences_update_own" on public.portal_preferences for update to authenticated using(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false) with check(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_favorites_select_own" on public.portal_favorites for select to authenticated using(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_favorites_insert_own" on public.portal_favorites for insert to authenticated with check(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_favorites_update_own" on public.portal_favorites for update to authenticated using(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false) with check(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_favorites_delete_own" on public.portal_favorites for delete to authenticated using(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_history_select_own" on public.portal_history for select to authenticated using(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_history_insert_own" on public.portal_history for insert to authenticated with check(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_history_update_own" on public.portal_history for update to authenticated using(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false) with check(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_history_delete_own" on public.portal_history for delete to authenticated using(user_id=(select auth.uid()) and coalesce((select auth.jwt()->>'is_anonymous')::boolean,false)=false);
create policy "portal_announcements_public_read" on public.portal_announcements for select to anon,authenticated using(published=true and starts_at<=now() and (ends_at is null or ends_at>now()));
create policy "portal_requests_public_insert" on public.portal_requests for insert to anon,authenticated with check(char_length(message) between 5 and 500 and (user_id is null or user_id=(select auth.uid())));
grant select,insert,update,delete on public.portal_preferences to authenticated;
grant select,insert,update,delete on public.portal_favorites to authenticated;
grant select,insert,update,delete on public.portal_history to authenticated;
grant select on public.portal_announcements to anon,authenticated;
grant insert on public.portal_requests to anon,authenticated;
